<template><div class="joint-controls" data-testid="joint-controls"><div v-if="!movable.length" class="dock-empty">没有可运动关节</div><JointSlider v-for="joint in movable" :key="joint.id" :joint="joint" :value="store.jointValues[joint.id]??0" @preview="store.previewJoint" @commit="store.queueJointCommit" /></div></template>
<script setup lang="ts">import {computed} from 'vue';import {useEditorStore} from '@/stores/editor';import JointSlider from './JointSlider.vue';const store=useEditorStore();const movable=computed(()=>store.scene.joints.filter(x=>!['fixed','planar','floating'].includes(x.type)))</script>
